import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"⚙️ 设置说明","description":"","frontmatter":{},"headers":[],"relativePath":"guide/settings.md","filePath":"guide/settings.md","lastUpdated":1787833646000}'),n={name:"guide/settings.md"};function i(l,t,s,d,h,p){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="⚙️-设置说明" tabindex="-1">⚙️ 设置说明 <a class="header-anchor" href="#⚙️-设置说明" aria-label="Permalink to &quot;⚙️ 设置说明&quot;">​</a></h1><h2 id="🔍-环境配置" tabindex="-1">🔍 环境配置 <a class="header-anchor" href="#🔍-环境配置" aria-label="Permalink to &quot;🔍 环境配置&quot;">​</a></h2><p>设置页面可以查看和配置运行环境。portable 包默认使用随应用提供的 Python 环境，也可以切换到 uv 或指定其他 Python：</p><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>🐍 Python</td><td>portable 包内置 Python ≥ 3.11 与所需依赖</td></tr><tr><td>🎞️ FFmpeg</td><td>portable 包内置 FFmpeg，也可指定其他路径</td></tr><tr><td>🛰️ yutto server</td><td>解析与下载的常驻后台，随应用自动启动 / 退出，可一键重启</td></tr></tbody></table><p>应用旁存在 <code>env</code> 时，首次启动会自动选择其中的 Python（Windows 为 <code>env/python.exe</code>，macOS 为 <code>env/bin/python</code>）。它和手动指定的 conda Python 使用相同的直接 Python 运行方式。切换到 uv 或其他 Python 并保存后，下次启动会继续使用保存的选择；开发构建与 portable 的配置语义一致。</p><h2 id="🛰️-yutto-server" tabindex="-1">🛰️ yutto server <a class="header-anchor" href="#🛰️-yutto-server" aria-label="Permalink to &quot;🛰️ yutto server&quot;">​</a></h2><p>解析与下载都由一个常驻的 yutto server 完成：应用打开时自动拉起、关闭时自动退出， 平时不需要关心它的存在。</p><p>「设置 → 环境状态」里可以看到它的运行状态和地址。如果解析 / 下载报 「与 yutto server 的连接已断开」，点旁边的「重启」即可恢复，详见 <a href="/troubleshooting/serve-restart.html">server 连接断开 / 启动失败</a>。</p><h2 id="💾-保存并重新检测" tabindex="-1">💾 保存并重新检测 <a class="header-anchor" href="#💾-保存并重新检测" aria-label="Permalink to &quot;💾 保存并重新检测&quot;">​</a></h2><p>点击「保存并重新检测」除了写入配置，还会<strong>自动重启 yutto server</strong>，让下载目录、 FFmpeg、代理和 Python 运行方式等设置立即生效。</p><div class="warning custom-block"><p class="custom-block-title">会中断进行中的任务</p><p>正在解析或下载时保存设置，这些任务会被切断（设置页会显示琥珀色提示，但不会拦截）。 建议等队列跑完再改设置。</p></div><h2 id="🎵-音频格式" tabindex="-1">🎵 音频格式 <a class="header-anchor" href="#🎵-音频格式" aria-label="Permalink to &quot;🎵 音频格式&quot;">​</a></h2><p>仅音频下载支持以下输出格式：</p><ul><li><strong>m4a</strong> — 默认格式，质量好体积小（直接保存原始音轨，无转码损耗）</li><li><strong>mp3</strong> — 兼容性最好（自动转码）</li><li><strong>flac</strong> — 无损格式（自动转码）</li><li><strong>wav</strong> — 无损无压缩（下载后本地转码）</li></ul><h2 id="🔑-账号登录" tabindex="-1">🔑 账号登录 <a class="header-anchor" href="#🔑-账号登录" aria-label="Permalink to &quot;🔑 账号登录&quot;">​</a></h2><p>通过扫码登录 Bilibili 账号，解锁高画质和大会员内容。</p><p>登录状态会保存在本地，下次启动无需重新登录。</p><h2 id="🌐-代理设置" tabindex="-1">🌐 代理设置 <a class="header-anchor" href="#🌐-代理设置" aria-label="Permalink to &quot;🌐 代理设置&quot;">​</a></h2><p>默认勾选「禁用代理」，解析、下载与封面加载将忽略系统或环境代理。</p><p>如需使用代理，取消勾选即可切换为自动模式。自动模式直接采用系统或环境中的代理配置：应用不会检测代理程序是否正在运行，也不会在代理连接失败后自动切换为直连。因此，代理程序未启动、退出后留下失效的系统代理，或环境变量指向不可用端口时，解析、下载和封面加载都可能失败；此时重新勾选「禁用代理」并重试即可。</p><h2 id="⚡-解析并发数" tabindex="-1">⚡ 解析并发数 <a class="header-anchor" href="#⚡-解析并发数" aria-label="Permalink to &quot;⚡ 解析并发数&quot;">​</a></h2><p>下载合集、收藏夹等批量内容时，应用会并发解析列表里的视频信息。</p><p>解析并发数控制同时解析多少个视频，默认为 8，上限 16：</p><ul><li>数值越大，解析越快</li><li>如果解析经常失败（风控 / 网络不稳），可以调小一些（最小为 1，即逐个解析）</li></ul><p>在「设置 → 一般设置」中修改，点击「保存并重新检测」后，下一次解析 / 下载即生效。</p>',25)])])}const b=e(n,[["render",i]]);export{u as __pageData,b as default};
